/*
	Line Walker Zoom #WCCChallenge "2 rules" 30.9.24 
	https://openprocessing.org/sketch/2375315
	#generativeart #creativecoding #p5js

  Dear Raph and creative coding community,

	a quick and simple one:
	  #1: zoom in every x frame
		#2: connect new point with last point with random color change
	Give it a bit of time to get blurry in the background.

	Best result, when blurry background, and big and small strctures are generated.

	Join the Birb's Nest Discord for friendly creative coding community
	and future challenges and contributions: https://discord.gg/S8c7qcjw2b
	WCCC-Contributions: https://openprocessing.org/curation/78544
*/

let lp, np, slc, len, clrs, clr, bg;

function setup() {
	// createCanvas(windowWidth, windowHeight);
	if (windowWidth * 0.75 > windowHeight) {
	  createCanvas(windowHeight / 0.75, windowHeight);	
	} else {
	  createCanvas(windowHeight * 0.75, windowHeight);	
	}

	describe("random line walker with defined angles and color from predefined palette zooming in giving an blury image with some detailed lines");
  frameRate(60);
  strokeWeight(~~random(3, 5.7));
  len = ~~(max(windowWidth, windowHeight) / random(8, 17));
  slc = ~~random(3, 9); // 3...8 #slices
  lp = { x: width / 2, y: height / 2 };
  blendMode(BLEND);
  clrs = shuffle(random(palettes));
  bg = clrs.pop();
	clr = color(random(clrs));
  stroke(clr);
  background(bg);
  loop();
}

function draw() {
  // rule 1: zoom in every x frame
  if (frameCount % 2 === 0) {
    const bg = get(0, 0, width, height);
		const dx = ~~(width*0.005); const dx2 = dx*2;
		const dy = ~~(height*0.005); const dy2 = dy*2;
    image(bg, -dx, -dy, width + dx2, height + dy2);
		lp.x = map(lp.x, 0, width-1, -dx, width+dx-1);
		lp.y = map(lp.y, 0, height-1, -dy, height+dy-1);
  }
  // rule 2: connect new point with last point with random color change
  np = { x: width, y: height }; // invalid next pt, forces while loop:
  while (np.x < 0 || np.x >= width - 1 || np.y < 0 || np.y >= height - 1) {
    const a = (~~random(slc) * TWO_PI) / slc;
    var dx = ~~(cos(a) * len);
    var dy = ~~(sin(a) * len);
    np = { x: lp.x + dx, y: lp.y + dy };
  }
	let dstClr = clr;
  if (random() < 0.15) dstClr = color(random(clrs)); // stroke(random(clrs));
  clrLine(lp.x, lp.y, np.x, np.y, clr, dstClr);
	clr = dstClr;
  lp = np;
}

function clrLine(x1, y1, x2, y2, c1, c2) {
	// const easings = [easeInOutElastic, easeInOutCubic, easeInCubic];
	// const easing = random(easings);
	const dst = dist(x1, y1, x2, y2);
	for (let i = 0; i <= dst; i++) {
		const f = i/dst;
		const x = lerp(x1, x2, f);
		const y = lerp(y1, y2, f);
		const c = lerpColor(c1, c2, f); // easing(f);
		stroke(c);
		point(x, y);
	}
}

function mousePressed() {
  if (mouseButton === LEFT) {
    if (isLooping() === true) {
      // noLoop() removed for animation
    } else {
      loop();
    }
  }
}

function doubleClicked() {
  if (mouseButton === LEFT) setup();
}
